    "explanation": "【何を聞かれているか】弟が兄に追いつく地点の、家からの道のり。\n【なぜそうなるのか】追いつくとは、2人が家から同じ道のりの地点にいる、ということである。兄は出発から t 分たったとき 80×t m、弟はそれより9分おくれて出発したので (t−9) 分走っていて 200×(t−9) m 進んでいる。この2つが等しくなる t を求めればよい。ダイヤグラム（時間と道のりのグラフ）では、2本の直線が交わる点にあたる。\n【ステップ1】兄が出発して t 分後に追いつくとする。兄の道のりは 80t m。\n【ステップ2】弟は (t−9) 分走るので、道のりは 200(t−9) m。\n【ステップ3】80t＝200(t−9) より 80t＝200t−1800、120t＝1800、t＝15。\n【ステップ4】追いついた地点は 80×15＝1200 m。\n【答え】1200m\n【確かめ】弟は 200×(15−9)＝200×6＝1200 m。兄の1200mと一致する。9時15分に追いつく。\n【よくあるまちがい】弟の走る時間を t 分と同じにして、兄の時間（t）と弟の時間（t−9）を区別しない。",
