    "explanation": "【何を聞かれているか】△APDの面積が21cm²になる時刻（2回あるかもしれない）。\n【なぜそうなるのか】動く点の問題では、点がどの辺の上にいるかで、三角形の底辺や高さの変わり方がちがう。そこで、点が通る辺ごとに場合分けして、面積を時間 x の式で表す。式ができたら、それぞれの範囲の中で、面積が21になる x を求める。範囲に入らない解は答えにならない。\n【ステップ1】AB上（0≦x≦5）：AP＝2x。△APD＝1/2×AD×AP＝1/2×6×2x＝6x。\n【ステップ2】BC上（5≦x≦8）：底辺AD＝6、高さAB＝10 で一定。△APD＝1/2×6×10＝30。21にならない。\n【ステップ3】CD上（8≦x≦13）：DP＝10−2(x−8)＝26−2x。△APD＝1/2×6×(26−2x)＝78−6x。\n【ステップ4】AB上：6x＝21 より x＝3.5（0≦x≦5に入る）。\n【ステップ5】CD上：78−6x＝21 より x＝9.5（8≦x≦13に入る）。\n【答え】3.5秒後と9.5秒後\n【確かめ】x＝3.5：AP＝7cm、1/2×6×7＝21。x＝9.5：DP＝26−19＝7cm、1/2×6×7＝21。どちらも面積21になる。\n【よくあるまちがい】3.5秒後だけを答えて、点PがCD上にいるときを忘れる。CD上の面積を、BC上と同じ30のままと考えてしまう。",
