    "explanation": "【何を聞かれているか】It is ... to 〜 の文で使う前置詞を選ぶ。\n【なぜそうなるのか】この形では、形容詞が人の性質（kind, nice, careful, foolish など）を表すときは of、ものごとの難しさ・可能さ（easy, difficult, important など）を表すときは for を使う。kind は「親切な」という人の性質なので、of you となる。「あなたが助けてくれたことは、あなたの親切さを表している」という関係である。\n【ステップ1】形容詞は kind。「親切な」は人の性質を表す語。\n【ステップ2】人の性質を表す形容詞のあとは of ＋人。ものごとの性質（easy など）なら for ＋人。\n【ステップ3】It was very kind of you to help me. で「手伝ってくれて、あなたはとても親切でした。」\n【答え】① of\n【確かめ】kind の代わりに easy を使うと、It was easy for you to help me. となり、for を使う。形容詞が何を説明しているかで使い分ける。\n【よくあるまちがい】It is ... for 〜 to ... をすべての形容詞に使えると思い、for を選ぶ。",
