    "explanation": "【何を聞かれているか】語を正しい順にならべて、3番目と5番目の語を答える。\n【なぜそうなるのか】「彼女がなぜ怒っているのか」は、why のあとに〈she is angry〉と主語＋動詞の順で続ける間接疑問である。文全体は、I don't know ＋（why she is angry）という構造になる。\n【ステップ1】文の骨組みは「私はわかりません」＝I don't know。\n【ステップ2】know のあとに、間接疑問 why she is angry を置く。why のあとは主語（she）、動詞（is）、補語（angry）の順。\n【ステップ3】完成した文は I don't know why she is angry.\n【ステップ4】1番目 I、2番目 don't、3番目 know、4番目 why、5番目 she、6番目 is、7番目 angry。\n【答え】③ know－she\n【確かめ】I don't know why she is angry. を日本語に直すと「私は、彼女がなぜ怒っているのかわかりません。」で、問題文と合う。\n【よくあるまちがい】why is she angry の語順（疑問文の語順）にしてしまい、3番目が why、5番目が angry になる。",
