    "passage": "Last winter, my school held a \"No Phone Day.\" On that day, all of us left our smartphones in a box at the entrance and did not use them until the last class ended. At first, many students were not happy. I was one of them. I kept checking my pocket, because I was used to looking at my phone every few minutes.\nDuring lunch time, something interesting happened. The classroom, usually quiet because everyone looked at a small screen, became noisy. My classmates talked about their weekends, and some of them played cards. I talked with Aya, who sat next to me, for the first time in a month. We found that we both like the same band.\nAfter school, our teacher asked us, \"How was today?\" Most of us said, \"It was better than I expected.\" But some students said they felt worried because they could not contact their families. The teacher said, \"Phones are useful, so we don't have to stop using them. But it is important to decide when to use them.\"\nNow, I put my phone in my bag during meals. I think it helps me enjoy time with people around me."
