    "explanation": "【何を聞かれているか】先生が生徒に考えてほしいことを選ぶ。\n【なぜそうなるのか】先生は、「携帯は便利だから、使うのをやめる必要はない。でも、いつ使うかを決めることが大切だ」と言っている。But（しかし）のあとに、先生がいちばん伝えたいことが書かれている。\n【ステップ1】先生の言葉は第3段落の最後。\n【ステップ2】前半：Phones are useful（便利）、we don't have to stop（やめなくてよい）。\n【ステップ3】後半：But it is important to decide when to use them.（でも、いつ使うかを決めることが大切）。\n【ステップ4】この内容に合うのは、② だけ。\n【答え】② It is important to decide when to use phones.\n【確かめ】先生は使用を禁止していない（①③④は先生の言葉と反対）。\n【よくあるまちがい】① のような「学校では使わない」と読んでしまう。先生は「使ってはいけない」とは言っていない。",
