    "answer": "My best memory is the school chorus contest last year. Our class practiced hard every day after school. When we sang on the stage, I felt very proud of my classmates.",
    "hint": "何の行事か、いつか、そのとき何をしたか、どう感じたかを、順番に書くとまとまる。",
    "explanation": "【何を聞かれているか】学校行事の思い出を、理由や気持ちを入れて英語で書く。\n【なぜそうなるのか】自由英作文では、むずかしい表現を使うより、自分が確実に正しく書ける文を、順序よく並べることが大切である。「何のできごとか」→「そのときの様子」→「気持ち」の順に書くと、理由もはっきりして、30語程度におさまる。時制をそろえて、過去のできごとは過去形で書く。\n【ステップ1】書き出し：My best memory is ～.（いちばんの思い出は〜です）で、行事を1つ決める。\n【ステップ2】具体的な説明：練習したこと・当日のことを、過去形で1〜2文書く。\n【ステップ3】気持ち：I felt ～（私は〜と感じた）で、理由や感想を書く。\n【ステップ4】語数を確認し、30語前後（25〜40語）になっていれば十分。\n【答え】My best memory is the school chorus contest last year. Our class practiced hard every day after school. When we sang on the stage, I felt very proud of my classmates.\n【確かめ】語数は31語。過去形（practiced, sang, felt）がそろっていて、文法のまちがいもない。（これは1つの例で、ほかの行事でもよい。）\n【よくあるまちがい】日本語の言いまわしを直訳して、主語や動詞のない文になる。時制が文ごとにばらばらになる。",
