    "answer": "I think students should wear school uniforms. First, we don't have to choose our clothes every morning, so we can save time. Second, uniforms make students feel like members of the same school. For these reasons, I like school uniforms.",
    "hint": "最初に賛成か反対かをはっきり書く。そのあと、First, … Second, … で理由を2つ。",
    "explanation": "【何を聞かれているか】制服についての意見を、理由を2つ入れて英語で書く。\n【なぜそうなるのか】意見を書く英作文は、〈意見→理由1→理由2→まとめ〉の順に書くと、読む人にわかりやすい。First, Second などの言葉を使うと、理由がいくつあるのかがはっきりする。賛成でも反対でもよいが、理由が意見とつながっていることが大切である。\n【ステップ1】意見：I think students should wear school uniforms.（賛成の場合）。\n【ステップ2】理由1：First, ～. 毎朝、服を選ばなくてよいので時間を節約できる。\n【ステップ3】理由2：Second, ～. 同じ学校の一員という気持ちになれる。\n【ステップ4】まとめ：For these reasons, ～. で結ぶ。\n【答え】I think students should wear school uniforms. First, we don't have to choose our clothes every morning, so we can save time. Second, uniforms make students feel like members of the same school. For these reasons, I like school uniforms.\n【確かめ】語数は40語。意見・理由2つ・まとめの形になっている。反対の意見（個性が出せない、など）でも、理由が2つあれば同じ形で書ける。\n【よくあるまちがい】理由が意見とずれている。First だけで Second が書かれていない。",
