    "explanation": "【何を聞かれているか】漢字の読みを、ひらがなで答える。\n【なぜそうなるのか】「功績」は、「立派なはたらき・成しとげた手がら」を表す熟語。「功」は音読みで「コウ」、「績」は音読みで「セキ」と読む。「成績（せいせき）」の「績」と同じ字と読み方である。熟語の読みは、知っている別の熟語（成功・成績）と結びつけて覚えると、まちがえにくい。\n【ステップ1】「功」は、「成功（せいこう）」「功労（こうろう）」の「コウ」。\n【ステップ2】「績」は、「成績（せいせき）」「業績（ぎょうせき）」の「セキ」。\n【ステップ3】つなげて「こうせき」。\n【答え】こうせき\n【確かめ】「功績をたたえる」「功績を残す」のように使う。「公績」「口績」などの字と取りちがえないこと。\n【よくあるまちがい】「こうしゃく」「こうぜき」など、濁音や拗音をまちがえて読む。",
