    "explanation": "【何を聞かれているか】空所に入る接続語を選ぶ。\n【なぜそうなるのか】接続語は、前の文と後ろの文の関係で選ぶ。空所の前は「沈黙は悪者あつかいされ、人はあわてる」という世の中の見方を述べている。空所のあとは、その見方を疑って「本当に沈黙は失敗なのか」と問いかけている。前の内容に対して、反対の方向へ話を転じているので、逆接の「しかし」が入る。\n【ステップ1】前の文：沈黙は悪者あつかいされる、という世の中の見方。\n【ステップ2】後ろの文：それを疑う問いかけ（本当に失敗なのだろうか）。\n【ステップ3】前と反対の方向に話を進めるつなぎの語は、逆接の「しかし」。\n【ステップ4】「だから」は順接、「たとえば」は例の提示、「つまり」は言いかえで、どれも合わない。\n【答え】イ　しかし\n【確かめ】空所に「しかし」を入れて読む。「…あわてて何かを言おうとする。しかし、本当に沈黙は、会話の失敗なのだろうか。」となり、話がなめらかにつながる。\n【よくあるまちがい】「つまり」を入れて、前の内容の言いかえだと誤解する（後ろは疑問で、反対の方向に進んでいる）。",
