    "passage": "会話の中で、沈黙はたいてい悪者あつかいされる。話がとぎれると、気まずい空気が流れ、人はあわてて何かを言おうとする。（ ① ）、本当に沈黙は、会話の失敗なのだろうか。\nたとえば、深刻な悩みを打ち明けられた場面を考えてみよう。そのとき、すぐに気のきいた助言を返せる人は少ない。多くの場合、相手の話を受けとめて、しばらく黙りこむことになる。この沈黙は、「あなたの話を軽く扱わず、考えている」というしるしとして働く。もし、聞いたとたんに明るい声で励ましの言葉を返せば、相手は、自分の悩みが簡単に片づけられたように感じるかもしれない。\nこのように、沈黙は、言葉が足りないことではなく、言葉にならないほど重い思いを共有していることの表れである場合がある。ところが、私たちは、沈黙を「何も伝わっていない時間」と決めつけがちである。それは、会話の価値を、交わした言葉の量ではかる習慣が身についているからだろう。\nしかし、会話の質は、言葉の量で決まるものではない。大切なのは、相手の言葉を待つ余裕である。言葉を急がず、沈黙を恐れない人は、結果として、相手から多くのことを聞き出すことができる。沈黙とは、会話をやめることではなく、相手に話す場所をゆずることなのだ。"
