    "explanation": "【何を聞かれているか】先生の動作と自分の動作を区別して、敬語に直す。\n【なぜそうなるのか】敬語は、動作をするのがだれかによって使いわける。先生（目上の人）の動作は、先生を高める尊敬語にする。自分の動作は、へりくだる謙譲語にする。この文では、「来ますか」の主語は先生なので、「来る」の尊敬語「いらっしゃる」を使う。「見ました」の主語は私なので、「見る」の謙譲語「拝見する」を使う。\n【ステップ1】「先生も来ますか」→主語は先生。「来る」の尊敬語は「いらっしゃる」。「いらっしゃいますか」にする。\n【ステップ2】「私は、先生の資料を見ました」→主語は私。「見る」の謙譲語は「拝見する」。「拝見しました」にする。\n【ステップ3】「わかりやすかったです」は、そのままでもよい（自分の感想で、丁寧語として成り立っている）。\n【答え】先生、明日の発表会に先生もいらっしゃいますか。私は、先生の資料を拝見しました。わかりやすかったです。\n【確かめ】敬語を入れかえた文を読み直す。主語が先生のところ（いらっしゃる）と、自分のところ（拝見する）で、使い分けられている。\n【よくあるまちがい】「来られますか」と尊敬の助動詞だけで直し、「拝見した」を「ご覧になりました」と尊敬語にしてしまう（自分の動作に尊敬語を使ってはいけない）。",
